record.field:
{
                "type": "object",
                "properties": {
                    "customer": {"type": "string", "description": "Nombre (parcial) del cliente a filtrar. Vacío = todos los clientes."},
                    "product": {"type": "string", "description": "Nombre (parcial) o referencia interna (código) del producto. Solo se aplica con group_by=product/product_day."},
                    "date_from": {"type": "string", "description": "Fecha inicio YYYY-MM-DD. Vacío = sin límite."},
                    "date_to": {"type": "string", "description": "Fecha fin YYYY-MM-DD. Vacío = sin límite."},
                    "group_by": {"type": "string", "enum": ["customer", "day", "customer_day", "product", "product_day", "total"], "description": "Cómo agrupar: customer/day/customer_day/total totalizan importes; product/product_day dan el detalle por producto (con lote)."}
                }
            }
